import Foundation
import Testing
@testable import PixlLibrary

/// The stage 2a golden vectors of the music brain (docs/brain-spec.md, 10.4): `mixes`, `why`, `snapshot`,
/// `repetition` and `eval`. The files in `Fixtures/brain` are GENERATED by the Android repo's
/// `./gradlew :brain:generateGolden` and copied here unchanged (`README.md` beside them says how each `fn` is
/// replayed). Same method as `BrainGoldenTests`: rebuild the canonical `"out":{...}` text and compare the bytes.
@Suite("Brain stage 2a golden vectors (brainMatchesAndroid)")
struct BrainMixGoldenTests {
    typealias G = BrainGoldenTests

    // MARK: mixes.jsonl

    static func mixRequest(_ input: BrainJson.Value, _ r: BrainJson.Value) -> MixPlanner.Request {
        let served: [Int64: Int32] = Dictionary(
            uniqueKeysWithValues: G.array(r, "servedTimes").map { row -> (Int64, Int32) in
                let a = row.arrayValue ?? []
                return (a[0].longValue ?? 0, Int32(truncatingIfNeeded: a[1].bareLong ?? 0))
            })
        let edges = G.array(r, "edges").map { row -> MixPlanner.Edge in
            let a = row.arrayValue ?? []
            return MixPlanner.Edge(a: a[0].longValue ?? 0, b: a[1].longValue ?? 0, weight: a[2].doubleValue ?? .nan)
        }
        return MixPlanner.Request(
            kind: G.int(r, "kind"),
            candidates: G.candidates(input),
            seeds: G.seeds(input),
            nowMs: G.long(r, "nowMs"),
            tzOffsetMin: G.int(r, "tzOffsetMin"),
            nuMultiplier: G.double(r, "nuMultiplier"),
            salt: G.long(r, "salt"),
            regenerate: G.int(r, "regenerate"),
            excludedRids: Set(G.longs(r, "excludedRids")),
            servedTimes: served,
            edges: edges,
            count: Int(G.int(r, "count"))
        )
    }

    @Test func mixesMatchAndroid() throws {
        var report = G.Report(file: "mixes.jsonl")
        for c in try G.cases("mixes.jsonl") {
            guard c.fn == "mix", let r = c.input["request"] else {
                report.record(c, false)
                continue
            }
            let affinity = Replay.rebuild(G.events(c.input, "history"), facts: G.facts(c.input), nowMs: G.long(c.input, "nowMs"))
            let request = Self.mixRequest(c.input, r)
            let plan = MixPlanner.plan(request, affinity: affinity)
            let nu = MixPlanner.nuOf(request.kind, multiplier: request.nuMultiplier)
            let tie = MixPlanner.tieSeedOf(request)
            report.record(c, c.matches {
                G.writePlan(&$0, "plan", plan)
                $0.double("nu", nu)
                $0.long("tieSeed", tie)
            })
        }
        report.verify(atLeast: 30)
    }

    // MARK: why.jsonl

    @Test func whyLinesMatchAndroid() throws {
        var report = G.Report(file: "why.jsonl")
        for c in try G.cases("why.jsonl") {
            let i = c.input
            let why = WhyLine.pick(
                arm: G.int(i, "arm"), slotKind: G.int(i, "slotKind"), homeRow: G.bool(i, "homeRow"),
                candidateAid: G.long(i, "candidateAid"), seedAid: G.long(i, "seedAid"), bestRank: G.int(i, "bestRank"),
                likedRid: G.long(i, "likedRid"), homeSeedRid: G.long(i, "homeSeedRid"),
                trackAffRecent: G.double(i, "trackAffRecent"), trackPosRecent: G.double(i, "trackPosRecent"),
                mix: G.bool(i, "mix"))
            report.record(c, c.fn == "why" && c.matches {
                $0.string("key", WhyLine.nameOf(why.key))
                $0.long("arg", why.arg)
            })
        }
        report.verify(atLeast: 100)
    }

    // MARK: snapshot.jsonl

    @Test func snapshotsMatchAndroid() throws {
        var report = G.Report(file: "snapshot.jsonl")
        for c in try G.cases("snapshot.jsonl") {
            let state = Replay.rebuild(G.events(c.input, "events"), facts: G.facts(c.input), nowMs: G.long(c.input, "nowMs"))
            let text = Snapshot.encode(state)
            report.record(c, c.fn == "snapshot" && c.matches { $0.string("text", text) })
        }
        report.verify(atLeast: 8)
    }

    @Test func aSnapshotReadsBackToTheSameState() throws {
        for c in try G.cases("snapshot.jsonl") {
            let state = Replay.rebuild(G.events(c.input, "events"), facts: G.facts(c.input), nowMs: G.long(c.input, "nowMs"))
            let text = Snapshot.encode(state)
            let back = try Snapshot.decode(text)
            #expect(Snapshot.encode(back) == text)
        }
    }

    @Test func aTextThatIsNotASnapshotIsRefused() {
        #expect(throws: Snapshot.Failure.self) { try Snapshot.decode("[]") }
        #expect(throws: Snapshot.Failure.self) { try Snapshot.decode("{\"format\":\"other\",\"rows\":[]}") }
        #expect(throws: Snapshot.Failure.self) { try Snapshot.decode("{\"format\":\"brain-snapshot-v1\"}") }
        #expect(throws: Snapshot.Failure.self) { try Snapshot.decode("{\"format\":\"brain-snapshot-v1\",\"rows\":[[\"1\"]]}") }
    }

    // MARK: repetition.jsonl

    @Test func repetitionMatchesAndroid() throws {
        var report = G.Report(file: "repetition.jsonl")
        for c in try G.cases("repetition.jsonl") {
            let i = c.input
            switch c.fn {
            case "servedPenalty":
                let p = Repetition.servedPenalty(G.int(i, "times"))
                report.record(c, c.matches { $0.double("penalty", p) })
            case "mixDay":
                let d = Repetition.mixDay(G.long(i, "ms"), tzOffsetMin: G.int(i, "tzOffsetMin"))
                report.record(c, c.matches { $0.long("day", d) })
            case "served":
                let lists = G.array(i, "lists").map {
                    Repetition.Served(surface: G.int($0, "surface"), builtAtMs: G.long($0, "builtAtMs"), rids: G.longs($0, "rids"))
                }
                let now = G.long(i, "nowMs")
                let tz = G.int(i, "tzOffsetMin")
                let times = Repetition.timesServed(lists, nowMs: now)
                let taken = Repetition.takenOnDay(lists, nowMs: now, tzOffsetMin: tz, exceptSurface: G.int(i, "exceptSurface"))
                report.record(c, c.matches {
                    $0.beginArray("timesServed")
                    for k in times.keys.sorted() {
                        $0.beginArray()
                        $0.longItem(k)
                        $0.intItem(times[k]!)
                        $0.endArray()
                    }
                    $0.endArray()
                    $0.longs("taken", taken.sorted())
                })
            default:
                report.record(c, false)
            }
        }
        report.verify(atLeast: 50)
    }

    // MARK: eval.jsonl

    static func writeSkipReport(_ w: inout BrainJson.Writer, _ r: Eval.SkipReport) {
        w.beginObject("report")
        w.int("trainEvents", r.trainEvents); w.int("heldOutEvents", r.heldOutEvents)
        w.int("finished", r.finished); w.int("skipped", r.skipped)
        w.double("brainAuc", r.brainAuc)
        w.beginArray("baselines")
        for i in r.baselineNames.indices {
            w.beginObject()
            w.string("name", r.baselineNames[i]); w.double("auc", r.baselineAuc[i]); w.double("delta", r.delta[i])
            w.double("low", r.deltaLow[i]); w.double("high", r.deltaHigh[i])
            w.endObject()
        }
        w.endArray()
        w.double("calibrationError", r.calibrationError)
        w.endObject()
    }

    static func candidateList(_ input: BrainJson.Value, _ name: String) -> [Candidate] {
        G.array(input, name).map {
            Candidate(rid: G.long($0, "rid"), aid: G.long($0, "aid"), albumKey: G.long($0, "albumKey"),
                      inLibrary: G.bool($0, "inLibrary"), liked: G.bool($0, "liked"),
                      fromArtistRadio: G.bool($0, "fromArtistRadio"), boostLn: G.double($0, "boostLn"))
        }
    }

    @Test func evalMatchesAndroid() throws {
        var report = G.Report(file: "eval.jsonl")
        for c in try G.cases("eval.jsonl") {
            let i = c.input
            switch c.fn {
            case "auc":
                let keys = G.longs(i, "keys")
                let labels = G.array(i, "finished").map { ($0.bareLong ?? 0) == 1 }
                let a = Eval.auc(keys, labels)
                report.record(c, c.matches { $0.double("auc", a) })
            case "skipPrediction":
                let config = Eval.Config(resamples: Int(G.int(i, "resamples")), seed: G.long(i, "seed"))
                let r = Eval.skipPrediction(G.events(i, "events"), facts: G.facts(i), config: config)
                report.record(c, c.matches { Self.writeSkipReport(&$0, r) })
            case "listHealth":
                let finish: [Int64: Double] = Dictionary(
                    uniqueKeysWithValues: G.array(i, "finishRates").map { row -> (Int64, Double) in
                        let a = row.arrayValue ?? []
                        return (a[0].longValue ?? 0, a[1].doubleValue ?? .nan)
                    })
                let world = Eval.HealthWorld(library: Self.candidateList(i, "library"), novel: Self.candidateList(i, "novel"),
                                             seeds: G.seeds(i), finishRate: finish)
                let start = try Snapshot.decode(G.string(i, "snapshot"))
                let h = Eval.listHealth(world, start: start, days: Int(G.int(i, "days")), nowMs: G.long(i, "nowMs"),
                                        tzOffsetMin: G.int(i, "tzOffsetMin"), salt: G.long(i, "salt"))
                report.record(c, c.matches {
                    $0.int("days", h.days); $0.double("distinctRatio", h.distinctRatio)
                    $0.double("maxArtistShare", h.maxArtistShare); $0.double("maxNoveltyGap", h.maxNoveltyGap)
                    $0.int("maxSameDayOverlap", h.maxSameDayOverlap); $0.int("shortestList", h.shortestList)
                })
            default:
                report.record(c, false)
            }
        }
        report.verify(atLeast: 17)
    }
}
